  max_tokens: 8000,
  tools: [
    {
      name: "submit_article",
      description: "生成したSEO記事を提出する",
      input_schema: {
        type: "object",
        properties: {
          title: { type: "string" },
          meta_description: { type: "string" },
          body_md: { type: "string", description: "Markdown, 2000字以上（上限は気にしなくてよいが、不自然に間延びさせない）。[IMAGE_N]プレースホルダーを含む" },
          tags: { type: "array", items: { type: "string" } },
          images: {
            type: "array",
            description: "本文中に挿入する画像。最大3枚(別途アイキャッチ1枚と合わせて記事全体で最大4枚になるため)",
            items: {
              type: "object",
              properties: {
                marker: { type: "string" },
                alt_text: { type: "string" },
                content_prompt: { type: "string" }
              },
              required: ["marker", "alt_text", "content_prompt"]
            }
          },
          eyecatch_prompt: { type: "string", description: "アイキャッチ画像の内容説明(記事全体を象徴する1枚。ブランドの世界観やタイトル描画の指示は不要、内容の説明のみでよい)" }
        },
        required: ["title", "meta_description", "body_md", "tags", "images", "eyecatch_prompt"]
      }
    }
  ],
  tool_choice: { type: "tool", name: "submit_article" },
  system: "あなたは career-uranai.site のSEO記事作成担当です。キャラクター「白石玲子｜キャリア未来鑑定士」の一人称・口調で書く（詳細ルール: automation/n8n/docs/workflow-design.md 1章、unified_fortuneTelling/docs/reiko-character.md）。読者の悩みに寄り添い、不安を煽らず、転職を断定的に勧めない。記事末尾は無料/精密診断への自然な誘導で締める。\n\n事前に調べた競合記事リサーチ結果を参考に、内容が薄くならないようにすること（そのまま転載せず、差別化ポイントを踏まえて独自の切り口で書く）。\n\nbody_md中で強調したい語句は全角の「」または**太字**を使うこと。半角ダブルクォート(\")は使わないこと。\n\ntitleのルール: 検索結果でタイトルの先頭30文字程度しか表示されなくても「転職・キャリアに関する記事」だと伝わるよう、タイトルの最初の20文字以内に「転職」「キャリア」などのキーワードを含めること。そのうえで具体的な手法・切り口（占術名など）を続け、最後に抽象的な結論やベネフィットを置く（例:「転職タイミングを西洋占星術×九星気学×MBTIで見極める｜迷いを手放す3つの視点」）。\n\n画像プランのルール: 表形式で比較したい内容や、視覚的に伝えたほうがわかりやすい箇所があれば、Markdown表の代わりに [IMAGE_1] [IMAGE_2] [IMAGE_3] のようなプレースホルダーを本文中の該当箇所に単独の行として挿入し、imagesという配列でその内容を指定すること。**本文画像は最大3枚まで**（多すぎないように、本当に必要な箇所だけに絞る）。content_promptにはブランドの世界観（ゴールド×バイオレットの配色、占星術的で上品な雰囲気）は書かなくてよい（別途固定で付与されるため）。画像に含めたい日本語のラベル・数値・見出しがあれば具体的に書くこと。\n\neyecatch_promptのルール: 記事全体を1枚で象徴する内容を書くこと（例: 3つの占術のモチーフを組み合わせた構図、記事のテーマを一目で表すシンボリックな絵）。ブランドの世界観やタイトルの描画についてはここに書かなくてよい（別途固定で付与される）。\n\ntagsのルール: 次の語彙の中からのみ選ぶこと。記事のターゲット・内容に合っているものを選ぶ（個数の上限は気にしなくてよいが、内容と無関係なものは選ばない）。語彙: " + JSON.stringify($('タグ語彙を取得').first().json.tagGroups.flatMap(g => g.options.map(o => o.value)))
  ,
  messages: [
    { role: "user", content: `対策キーワード: ${$('入力データ確定').first().json.main_keyword}\n想定読者: ${$('入力データ確定').first().json.target_reader}\n差別化ポイント: ${$('入力データ確定').first().json.differentiation}\n\n競合記事リサーチ結果:\n${$json.competitor_research}` }
  ]
}) }}

parameters.jsCode:
// Claudeのtool_use出力(input)は既にパース済みオブジェクトなので、JSON.parseは不要
const content = $input.first().json.content ?? [];
const toolUse = content.find(b => b.type === 'tool_use' && b.name === 'submit_article');
if (!toolUse) {
  throw new Error('Claude応答にtool_useブロックが見つかりませんでした: ' + JSON.stringify(content).slice(0, 300));
}
const parsed = toolUse.input;
return [{
  json: {
    title: parsed.title,
    meta_description: parsed.meta_description,
    body_md: parsed.body_md,
    tags: parsed.tags ?? [],
    status: 'draft',
    images: parsed.images ?? [],
    eyecatch_prompt: parsed.eyecatch_prompt ?? ''
  }
}];

// 手動実行(入力例)・サブワークフロー実行トリガーのどちらから来ても、
// main_keyword/target_reader/differentiationを持つitemをそのまま次に渡す
return $input.all();

// Geminiのレスポンス(candidates[0].content.parts[].text)から競合記事リサーチ要約を取り出す
const item = $input.first().json;
const parts = item.candidates?.[0]?.content?.parts ?? [];
const competitor_research = parts.map(p => p.text ?? '').join('\n').trim() || '（競合記事リサーチを取得できませんでした。Gemini credentialの設定を確認してください）';
return [{ json: { competitor_research } }];

// レスポンス整形で得たimages[](本文用・最大3枚)とeyecatch_prompt(1枚)を、
// 合計最大4枚のitemに展開する。
// ブランドの世界観（配色・雰囲気）はここで固定文言として必ず付与し、
// 記事ごとにばらつかないようにする(ユーザー要望: 全生成画像で世界観を統一する)。
// アイキャッチのみ、タイトル文字を画像内に必ず描画するよう追加指示する(ユーザー要望)。
const STYLE_PREFIX = "ゴールド×バイオレットのグラデーションを基調にした、上品で神秘的な占星術テイストのイラスト。過度に装飾せずシンプルで洗練されたデザイン。星・惑星・幾何学模様のモチーフを控えめに使用。写実的すぎないフラットまたはソフトなグラデーション調のイラストスタイル。文字を含める場合は日本語として正確に読みやすく描画すること。横長(16:9〜3:2程度)の構図。";

const article = $input.first().json;
const results = [];

// 本文用画像(最大3枚、念のためここでも上限を強制する)
const images = (Array.isArray(article.images) ? article.images : []).slice(0, 3);
for (const img of images) {
  results.push({
    json: {
      marker: img.marker,
      alt_text: img.alt_text,
      is_eyecatch: false,
      image_prompt: `${STYLE_PREFIX}\n\n描く内容: ${img.content_prompt}`
    }
  });
}

// アイキャッチ画像(1枚、タイトルを必ず描画させる)
if (article.eyecatch_prompt) {
  results.push({
    json: {
      marker: '__EYECATCH__',
      alt_text: article.title,
      is_eyecatch: true,
      image_prompt: `${STYLE_PREFIX}\n\n描く内容: ${article.eyecatch_prompt}\n\nこの画像には記事タイトル「${article.title}」を、読みやすい日本語のテキストとして画像内に大きく配置すること（タイトルの描画は必須）。`
    }
  });
}

return results;

// OpenAIのレスポンス(data[0].b64_json)をn8nのbinaryデータに変換する。
// runOnceForEachItemモードのため、単一オブジェクトを直接returnする(配列でラップしない)。
// Gemini画像品質チェックでNGと判定された場合もfailedとして扱う(本文への差し込みをスキップする)。
let orig = null;
let origError = null;
try {
  orig = $('画像プロンプトを展開').item.json;
} catch (e) {
  origError = String((e && e.message) || e);
}

let qaFailed = false;
try {
  const qaJson = $('Geminiで画像品質チェック').item.json;
  const qaText = (qaJson?.candidates?.[0]?.content?.parts ?? []).map(p => p.text || '').join('');
  if (qaText.includes('NG')) qaFailed = true;
} catch (e) {
  // チェック自体が失敗した場合はスキップしない(付加的なチェックのため)
}

try {
  const b64 = $('OpenAIで画像生成').item.json.data?.[0]?.b64_json;
  if (!b64) {
    return { json: { marker: orig?.marker ?? null, alt_text: orig?.alt_text ?? null, failed: true, reason: 'no_b64_in_response', orig_error: origError } };
  }
  if (qaFailed) {
    return { json: { marker: orig?.marker ?? null, alt_text: orig?.alt_text ?? null, failed: true, reason: 'gemini_qa_ng' } };
  }
  const buffer = Buffer.from(b64, 'base64');
  const fileName = `${(orig?.marker ?? 'image').replace(/[^a-zA-Z0-9]/g, '')}.png`;
  const binary = await this.helpers.prepareBinaryData(buffer, fileName, 'image/png');
  return { json: { marker: orig?.marker ?? null, alt_text: orig?.alt_text ?? null, failed: false }, binary: { file: binary } };
} catch (e) {
  return { json: { marker: orig?.marker ?? null, alt_text: orig?.alt_text ?? null, failed: true, reason: 'exception', error_message: String((e && e.message) || e), orig_error: origError } };
}

// アップロード結果(HTTP Requestのレスポンスでjsonが上書きされ、marker等は失われている)を、
// 同じ順序で並んでいるはずの「Base64をBinaryに変換」の出力(marker/alt_textを保持)と
// 位置(index)で突き合わせて対応づける。
// __EYECATCH__は本文への差し込みではなくeyecatch_urlとして扱う。
const article = $('レスポンス整形').first().json;
let body = article.body_md || '';
let eyecatchUrl = null;

const uploadResults = $input.all();
const markerSource = $('Base64をBinaryに変換').all();

for (let i = 0; i < uploadResults.length; i++) {
  const marker = markerSource[i]?.json?.marker;
  if (!marker) continue;
  const uploadJson = uploadResults[i]?.json || {};
  const failed = !uploadJson.url;
  const altText = markerSource[i]?.json?.alt_text || '';

  if (marker === '__EYECATCH__') {
    if (!failed) eyecatchUrl = uploadJson.url;
    continue;
  }
  const replacement = failed ? '' : `![${altText}](${uploadJson.url})`;
  body = body.split(marker).join(replacement);
}
// 念のため残った[IMAGE_N]パターンも取り除く
body = body.replace(/\[IMAGE_\d+\]/g, '');

const result = {
  title: article.title,
  meta_description: article.meta_description,
  body_md: body,
  tags: article.tags,
  status: 'draft'
};
if (eyecatchUrl) result.eyecatch_url = eyecatchUrl;

return [{ json: result }];
